const seconds = 24 * 3600;
const targets = [21600];
const lap = 360 * 120;
let count = 0;
for (let s = 0; s < seconds; s++) {
  for (const t of targets) {
    const before = Math.floor((11 * s - t) / lap);
    const after = Math.floor((11 * (s + 1) - t) / lap);
    if (after > before) count++;
  }
}
return count;
